#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *p = (int *)malloc((N + 1) * sizeof(int));
    if (!p) return 0;

    long long inv_parity = 0; /* inversion count mod 2 */

    for (int i = 1; i <= N; i++) {
        scanf("%d", &p[i]);
        if (((long long)(p[i] - i)) & 1LL) {
            inv_parity ^= 1;
        }
    }

    /* 
       Each allowed operation reverses a strictly decreasing triple:
       (a,b,c) with a>b>c -> (c,b,a).
       This changes the permutation by one swap of positions i-1 and i+1,
       so inversion parity flips each move.

       Also, after every move, each element stays on the same parity of index
       (positions i-1 and i+1 have same parity, and i stays fixed).
       Therefore, for every value x, parity(position of x) is invariant.
       Since in the target permutation value x must be at position x,
       necessary condition: current position of x has same parity as x,
       i.e. p[i] and i have same parity for all i.

       This condition is also sufficient:
       with the parity-position condition satisfied, the permutation splits into
       independent permutations on odd and even positions. The total inversion
       parity is then even, and by the allowed local moves one can realize the
       needed adjacent swaps within each parity class, so sorting is possible.

       Thus the answer is YES iff p[i] % 2 == i % 2 for all i.
    */

    for (int i = 1; i <= N; i++) {
        if (((p[i] - i) & 1) != 0) {
            printf("No\n");
            free(p);
            return 0;
        }
    }

    printf("Yes\n");
    free(p);
    return 0;
}

