    for (int i = 0; i < N; i++) cin >> p[i];

    long long inv = 0;
    // Count inversions using Fenwick tree
    vector<int> bit(N + 1, 0);
    auto add = [&](int idx, int val) {
        for (; idx <= N; idx += idx & -idx)
            bit[idx] += val;
    };
    auto sum = [&](int idx) {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx)
            res += bit[idx];
        return res;
    };

    for (int i = 0; i < N; i++) {
        inv += i - sum(p[i]);
        add(p[i], 1);
    }

    if (inv % 2 == 0) cout << "Yes\n";
    else cout << "No\n";

    return 0;
}

