int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> p(N + 1);
    for (int i = 1; i <= N; ++i) cin >> p[i];

    // Operation:
    // if (a, b, c) are consecutive and a > b > c,
    // we can transform them into (c, b, a).
    //
    // This swaps positions i-1 and i+1, keeping the middle fixed.
    // Therefore each number always stays on the same parity of position.
    // So a necessary condition to reach identity is:
    // for every position i, p[i] and i have the same parity.
    //
    // It is also sufficient:
    // considering only odd positions and only even positions separately,
    // the operation acts like an adjacent swap inside each parity subsequence,
    // and whenever two same-parity elements are inverted, the corresponding
    // three consecutive values are strictly decreasing, so we can fix inversions.
    // Hence identity is reachable iff parity matches for all positions.

    for (int i = 1; i <= N; ++i) {
        if ((p[i] & 1) != (i & 1)) {
            cout << "No\n";
            return 0;
        }
    }

    cout << "Yes\n";
    return 0;
}

