public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = sc.nextInt();
        // BFS/DFS for small n, need pattern for large n
        // Use BFS
        String start = Arrays.toString(p);
        String goal = Arrays.toString(java.util.stream.IntStream.rangeClosed(1,n).toArray());
        if (start.equals(goal)) { System.out.println("Yes"); return; }
        Set<String> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.add(p);
        visited.add(start);
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            for (int i = 1; i < n-1; i++) {
                if (cur[i-1]>cur[i] && cur[i]>cur[i+1]) {
                    int[] next = cur.clone();
                    int tmp=next[i-1]; next[i-1]=next[i+1]; next[i+1]=tmp;
                    String ns = Arrays.toString(next);
                    if (ns.equals(goal)) { System.out.println("Yes"); return; }
                    if (!visited.contains(ns)) { visited.add(ns); queue.add(next); }
                }
            }
        }
        System.out.println("No");
    }
}

