public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] p = new int[N];
        for (int i = 0; i < N; i++) p[i] = fs.nextInt();

        // In one operation, a decreasing triple (a>b>c) becomes (c,b,a).
        // This swaps positions i-1 and i+1, so each element keeps the parity
        // of its position forever. Therefore, a necessary condition is:
        // for every value x, position(x) % 2 == x % 2.
        //
        // It is also sufficient:
        // considering odd and even positions separately, the operation acts like
        // swapping adjacent elements within one parity subsequence whenever the
        // middle element lies between them. This allows elimination of inversions,
        // and any permutation satisfying the parity condition can be sorted.
        //
        // So we only need to check parity of value and position.

        for (int i = 0; i < N; i++) {
            int pos1 = i + 1; // 1-based position
            if ((p[i] & 1) != (pos1 & 1)) {
                System.out.println("No");
                return;
            }
        }
        System.out.println("Yes");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

